# section 2
from fractions import Fraction as F
for a in range(1, 100):
    assert a // 1 == a and a // a == 1 and 0 // a == 0
assert all(c*0 == 0 for c in range(-1000, 1000))
assert 0*5 == 0 and 0*0 == 0 != 5 and 5*0 == 0 != 5
assert F(3, 12) < 1 and 3 % 12 != 0
assert (24 // 4) // 2 == 3 and 24 // (4 // 2) == 12 and 6 // 2 == 3 and 24 // 2 == 12
for a in range(0, 300):
    for b in range(1, 13):
        for c in range(1, 13):
            if a % (b*c) == 0:
                assert (a // b) // c == a // (b*c)
            if a % b == 0:
                for k in range(1, 6): assert (a*k) // (b*k) == a // b
for p in range(0, 100):
    for q in range(0, 100):
        for b in range(1, 10):
            if p % b == 0 and q % b == 0:
                assert (p + q) // b == p // b + q // b
                if p >= q: assert (p - q) // b == p // b - q // b
assert 16 == 2*8 and 720 // 2 == 360 and 360 // 8 == 45 and 720 // 16 == 45 and 720 // 4 == 180 and 16 // 4 == 4 and 180 // 4 == 45 and 45*16 == 720
for a in range(0, 60):
    for b in range(1, 15):
        for k in range(1, 6):
            assert ((a*k) % (b*k) == 0) == (a % b == 0)
assert 12 // (2 + 4) == 2 and 12 // 2 + 12 // 4 == 9 and 12 // 2 == 6 and 12 // 4 == 3
assert 7*0 == 0 and 5*0 == 0
# exercises
assert 0 // 9 == 0 and 9 // 9 == 1 and 9 // 1 == 9
assert (48 // 4) // 2 == 6 and 48 // 4 == 12 and 48 // (4 // 2) == 24 and 48 // 2 == 24 and 48 // 8 == 6 and 4*2 == 8
assert 360 // 40 == 36 // 4 == 9 and 630 // 70 == 63 // 7 == 9 and 9*40 == 360 and 9*70 == 630
assert 98 == 105 - 7 and 105 == 15*7 and 105 // 7 - 7 // 7 == 15 - 1 == 14 and 14*7 == 98
for a in range(1, 60):
    for b in range(1, 60):
        if a % b == 0 and b % a == 0: assert a == b
assert 600 // 3 == 200 and (6*100) // 3 == (6 // 3)*100
for a in range(1, 50): assert a // a == 1 and 0 // a == 0
